"👀 Des abonnés, comme Polarsteps : tes proches suivent le voyage (photos en vignettes et récits), mettent des ❤️ et des commentaires.":"👀 Polarsteps처럼 팔로워 기능: 가족과 친구가 여행을 팔로우하고(사진 썸네일과 여행기) ❤️와 댓글을 남겨요.",
"👥 Une fenêtre « Abonnés & partages », avec une pastille dès qu’il y a du nouveau.":"👥 “팔로워 및 공유” 창, 새 소식이 있으면 배지 표시.",
