"🛫 Escale (recherche de vols, Radar des prix) : pour respecter les règles de Google Play, Escale ne sera pas dans la version finale de Vezoria. Le module fait appel à trop de services extérieurs pour être publié.":"🛫 Escale(항공권 검색, 가격 레이더): Google Play 정책을 지키기 위해 Escale은 Vezoria 최종 버전에 포함되지 않습니다. 외부 서비스에 너무 많이 의존해서 출시할 수 없기 때문이에요.",
"🔕 Aucune notification : Vezoria ne t’envoie rien.":"🔕 알림 없음: Vezoria는 아무것도 보내지 않아요.",
"📥 L’import depuis Polarsteps n’est pas encore dans Vezoria.":"📥 Polarsteps 가져오기는 아직 Vezoria에 없어요.",
"Cette version test garde le stockage du carnet : même serveur, mêmes codes. Tes compagnons restés sur le carnet voient ce que tu fais dans Vezoria, et inversement.":"이 테스트 버전은 수첩과 같은 저장소를 씁니다: 같은 서버, 같은 코드. 수첩을 계속 쓰는 동행도 내가 Vezoria에서 한 일을 볼 수 있고, 그 반대도 마찬가지예요.",
"Avant la première ouverture de Vezoria, une copie de sauvegarde de ton carnet est gardée sur ce téléphone.":"Vezoria를 처음 열기 전에 수첩의 백업 사본이 이 휴대폰에 저장됩니다.",
