"Bloquer {0} ?\n\nSes commentaires et ❤️ sont masqués pour tous tes abonnés et elle est retirée de la liste.\nPour l’empêcher aussi de voir tes souvenirs, touche ensuite « 🔁 Nouveau lien abonné » et renvoie le lien seulement aux personnes de ton choix.":"{0}을(를) 차단할까요?\n\n이 사람의 댓글과 ❤️가 모든 팔로워에게 숨겨지고 목록에서도 제거됩니다.\n추억도 못 보게 하려면 이어서 “🔁 새 팔로워 링크”를 누르고, 원하는 사람에게만 링크를 다시 보내세요.",
"Créer un nouveau lien abonné ?\n\nL’ancien lien ne marchera plus : plus personne ne voit tes souvenirs tant que tu n’as pas renvoyé le nouveau lien. Les ❤️ et commentaires passés sont effacés.":"새 팔로워 링크를 만들까요?\n\n이전 링크는 더 이상 작동하지 않아요: 새 링크를 보내기 전까지 아무도 추억을 볼 수 없습니다. 지난 ❤️와 댓글은 삭제됩니다.",
