"Copie le texte de l’e-mail de réservation (vol, hôtel, train, bus…) et colle-le ici : l’appli repère la date, les horaires, la référence, la compagnie et le prix. Tu vérifies avant d’enregistrer. Rien n’est envoyé sur Internet.":"예약 메일(항공, 호텔, 기차, 버스…)의 내용을 복사해서 여기에 붙여 넣으세요: 앱이 날짜, 시간, 예약 번호, 항공사, 가격을 찾아내요. 저장하기 전에 확인할 수 있어요. 인터넷으로는 아무것도 보내지 않아요.",
"🔍 Analyser":"🔍 분석",
