"✅ Bonne période pour réserver ({0}–{1} semaines avant). Compare les prix sur les sites des compagnies.":"✅ 예약하기 좋은 시기예요 ({0}~{1}주 전). 항공사 사이트에서 가격을 비교하세요.",
"⚠️ Départ proche : les prix montent souvent. Compare vite (dates voisines, aéroports proches).":"⚠️ 출발이 가까워요: 가격이 오르기 쉬워요. 빨리 비교하세요 (가까운 날짜, 근처 공항).",
"· départ dans {0} semaine(s)":"· {0}주 후 출발",
