"Ordres de grandeur (distance à vol d’oiseau corrigée × facteurs moyens type ADEME), pas un calcul certifié. Conseils de réservation = tendances générales, pas une prédiction de prix.":"대략적인 규모(보정한 직선거리 × ADEME 방식 평균 계수)이며 인증된 계산이 아니에요. 예약 팁 = 일반적인 경향이며 가격 예측이 아니에요.",
